use super::*;
use crate::pet_runtime::recipe_decisions::Source;
#[test]fn native_transport_decision_consumes_the_original_generated_review_and_registers_before_effects() {
    let(f,a,g,_p,o,_)=crate::pet_runtime::generated_effect_tests::setup(true);let o=Arc::new(o);let bus=Bus::new();let player=Player::new(&bus,"Private native decision");let review=o.review_recipe_with_criteria(&g,&g.plans[0].id,"native-decision",Arc::new(Target::fixture_at(&bus.address).unwrap()),&config(),&[],crate::assistant_memory::now()).unwrap();
    let binding=o.recipe_input_binding(&g,&g.plans[0].id,&[]).unwrap();assert_eq!(binding,review.proposal().scope.verification);
    let store=Arc::new(Store::existing_verified(&f.path.join("goals"),&root(&f)).unwrap().unwrap());let source=Source::capture(o.clone(),&g,&review,store,Arc::new(||Ok(config()))).unwrap();assert_eq!(source.review()["existingGoalConsentOperation"],"goalPlanning");assert_eq!(source.review()["additionalModelPlanningGranted"],false);assert!(source.review()["recipe"]["steps"][0].get("intent").is_none());assert!(source.review()["recipe"]["steps"][0].get("criteria").is_none());
    let fixture=crate::cli_chat::goal_decision_fixture(source.clone());fixture.answer(json!({"allow":true}),fixture.request["goalTarget"].clone()).unwrap();let decision=fixture.decision().unwrap();assert!(decision.approved());assert!(!source.current());assert!(fixture.answer(json!({"allow":true}),fixture.request["goalTarget"].clone()).is_err());
    let(approved,ready)=review.approve_decision(decision,&o,&g,&config(),crate::assistant_memory::now()).unwrap();assert!(o.run_recipe(&g,&ready,||Ok(config()),|_|{}).is_err());register(&a,&g,&o,&approved,&ready);let result=o.run_recipe(&g,&ready,||Ok(config()),|_|{}).unwrap();assert!(result.progress.criteria_verified);assert_eq!(player.calls.lock().unwrap().len(),2);
}
#[test]fn a_native_decision_cannot_approve_a_different_retained_review_of_the_same_plan() {
    let(f,_a,g,_p,o,_)=crate::pet_runtime::generated_effect_tests::setup(true);let o=Arc::new(o);let bus=Bus::new();let player=Player::new(&bus,"Private wrong review");let target=Arc::new(Target::fixture_at(&bus.address).unwrap());let first=o.review_recipe_with_criteria(&g,&g.plans[0].id,"first-review",target.clone(),&config(),&[],crate::assistant_memory::now()).unwrap();let source=Source::capture(o.clone(),&g,&first,Arc::new(f.store()),Arc::new(||Ok(config()))).unwrap();let fixture=crate::cli_chat::goal_decision_fixture(source);fixture.answer(json!({"allow":true}),fixture.request["goalTarget"].clone()).unwrap();let decision=fixture.decision().unwrap();let second=o.review_recipe_with_criteria(&g,&g.plans[0].id,"other-review",target,&config(),&[],crate::assistant_memory::now()).unwrap();assert!(second.approve_decision(decision,&o,&g,&config(),crate::assistant_memory::now()).is_err());assert!(player.calls.lock().unwrap().is_empty());
}
#[test]fn a_large_admitted_goal_is_reviewed_once_without_changing_the_original_cli_limit() {
    let criteria=(0..32).map(|i|format!("Criterion {i}: {}","x".repeat(4080))).collect::<Vec<_>>();let(f,_a,g,_p,o,_)=setup_plan_criteria(sequence(),2,Arc::new(|_,_,_|Validity::Current),criteria);let o=Arc::new(o);let bus=Bus::new();let player=Player::new(&bus,"Private large review");let conditions=(0..32).map(|i|crate::pet_runtime::criteria::Input{criterion_index:i,predicate:crate::pet_runtime::criteria::Predicate::SpotifyVolume{percent:17}}).collect::<Vec<_>>();
    let review=o.review_recipe_with_criteria(&g,&g.plans[0].id,"large-review",Arc::new(Target::fixture_at(&bus.address).unwrap()),&config(),&conditions,crate::assistant_memory::now()).unwrap();let source=Source::capture(o,&g,&review,Arc::new(f.store()),Arc::new(||Ok(config()))).unwrap();assert_eq!(source.review()["recipe"]["criteria"],json!(g.spec.criteria));assert!(source.review()["recipe"]["steps"].as_array().unwrap().iter().all(|s|s.get("criteria").is_none()&&s.get("intent").is_none()));
    let fixture=crate::cli_chat::goal_decision_fixture(source);let bytes=serde_json::to_vec(&fixture.request).unwrap().len();assert!(bytes>256*1024&&bytes<=2*1024*1024);assert_eq!(fixture.count(),1);assert!(player.calls.lock().unwrap().is_empty());
}
#[test]fn generated_goal_proof_readers_coexist_while_grant_mutations_remain_exclusive(){
    use std::os::fd::AsRawFd;
    let(f,a,g,_p,o,_)=crate::pet_runtime::generated_effect_tests::setup(true);let owner=Arc::new(o);let bus=Bus::new();let player=Player::new(&bus,"Private concurrent proof readers");let review=owner.review_recipe_with_criteria(&g,&g.plans[0].id,"shared-proof",Arc::new(Target::fixture_at(&bus.address).unwrap()),&config(),&[],crate::assistant_memory::now()).unwrap();
    let store=Arc::new(Store::existing_verified(&f.path.join("goals"),&root(&f)).unwrap().unwrap());let source=Source::capture(owner.clone(),&g,&review,store.clone(),Arc::new(||Ok(config()))).unwrap();let fixture=crate::cli_chat::goal_decision_fixture(source.clone());let file=std::fs::OpenOptions::new().read(true).write(true).open(root(&f).join(".catalog.lock")).unwrap();assert_eq!(unsafe{libc::flock(file.as_raw_fd(),libc::LOCK_SH|libc::LOCK_NB)},0);
    assert!(source.current());assert_eq!(store.read(&g.id,&g.spec.owner.pet_id).unwrap().revision,g.revision);assert_eq!(fixture.panel_pending().len(),1);
    let row=&g.admissions[0];assert!(matches!(a.revoke(&row.spec,row.proof.as_ref().unwrap(),crate::assistant_memory::now()),Err(crate::pet_runtime::authority::Failure::Busy)));assert!(source.current());
    let other=source.clone();let reader=thread::spawn(move||for _ in 0..8{assert!(other.current());});for _ in 0..8{assert!(source.current());}reader.join().unwrap();
    fixture.panel_answer(true,fixture.request["goalTarget"].clone()).unwrap();assert!(fixture.decision().unwrap().approved());assert!(player.calls.lock().unwrap().is_empty());drop(file);
}
